\label{Thm:SR}
 Under Assumption~\ref{Ass:BEC} and~\ref{Ass:MIC},
 the following properties hold on the event $\mathcal{T}_{{\lambda}}$.
 \begin{enumerate}
   \item[(a)] $\ell_{\infty}$-bound: $\norm{{\hat{\beta}}_{{\lambda}}-{\beta^*}}_{\infty}\leq 1.5a{\lambda}/c_{\min}$\,;
   \item[(b)] support recovery: $\textnormal{supp}({\hat{\beta}}_{{\lambda}})\subset S$, and $\textnormal{supp}({\hat{\beta}}_{{\lambda}}) = S$ if $\min_{j \in S}|{\beta^*_j}|>1.5a{\lambda}/c_{\min}$\,.


 \end{enumerate}

Given $\delta\in (0,1)$, the oracle tuning parameter is
\begin{equation}
  {\lambda}_{\delta}^*= \arg\!\min_{{\lambda} \in \Lambda}\{\Pr(\mathcal{T}_{{\lambda}})\geq 1-\delta\}\,.
\end{equation}

     Given a constant $C\geq 1.5a/ c_{\min}$, we select the tuning parameter
     \begin{equation}\label{eqn:AV}
     \hat{{\lambda}}= \min\Big\{{\lambda}\in \Lambda\ :\
     {\norm{{\hat{\beta}}_{{\lambda}'}-{\hat{\beta}}_{{\lambda}''}}_{\infty}}\leq C{\lambda}'+C{\lambda}''~~\forall\, {\lambda}',{\lambda}''\geq {\lambda} \Big\}
     \end{equation}
and set
\begin{equation}\label{eset}
  \hat S=\{j\in[p]:|({\hat{\beta}}_{\hat{\lambda}})_j|\geq 3C\hat{\lambda}\}\,.
\end{equation}

   \label{Thm:AV}
     Under Assumption~\ref{Ass:BEC} and \ref{Ass:MIC}, for any $\delta\in (0,1)$ and $C\geq 1.5 a/c_{\min}$, the tuning parameter~$\hat{{\lambda}}$ from  \eqref{eqn:AV} provides with probability at least $1-\delta$
 \[\hat{{\lambda}}\leq {\lambda}_{\delta}^* \quad \text{and} \quad
 \norm{{\hat{\beta}}_{\hat{{\lambda}}}-{\beta^*}}_{\infty}\leq 3C{\lambda}_{\delta}^*\,,
\]
and, if $\min_{j \in S}|{\beta^*_j}|>6C{\lambda}_{\delta}^*,$
     \begin{equation*}
       \hat S \supset S\,.
     \end{equation*}

