The proof follows readily from Lemma~\ref{lem:L2norm}.
To see this, note that because $|X_{ij}|\leq 1$ for all $i\in [n]$ and $j\in [p]$, it holds that
  \begin{equation*}
    \begin{aligned}
      |r^{\top} x^j/n|=|\sum_{i=1}^n X_{ij}r_i/n|\leq \sum_{i=1}^n|X_{ij}
      ||r_i|/n\leq \sum_{i=1}^n|r_i|/n
      \end{aligned}
  \end{equation*}
    for all $j\in[p]$. By the closed form of $r_i$ in Equation~\eqref{eqn:ri}, it holds that
    $|\xi_i(t)|\leq 1$ for all $t\in[0,1]$, and since ${\hat{\alpha}_{{S}^c}}={\beta^*_{{S}^c}}=0$, we then get
    \begin{equation}\label{eqn:upperboundL2norm}
    \begin{aligned}
      |r^{\top} x^j/n|&\leq ({\hat{\alpha}_{S}}-{\beta^*_{S}})^\top\Big(\sum_{i=1}^n x_{i,S}x_{i,S}^\top/n\Big)({\hat{\alpha}_{S}}-{\beta^*_{S}})
      \\
      &=({\hat{\alpha}_{S}}-{\beta^*_{S}})^\top (X_{S}^\top X_{S}/n)({\hat{\alpha}_{S}}-{\beta^*_{S}})\\
      &=({\hat{\alpha}} - {\beta^*})^\top (X^\top X/n)({\hat{\alpha}}-{\beta^*})\\
      &\leq  c_{\max} \norm{{\hat{\alpha}_{S}}-{\beta^*_{S}}}_2^2\,.
    \end{aligned}
  \end{equation}
 Moreover,  because $\lambda \leq \gamma c_{\min}^2/(100(2-\gamma)sc_{\max})\leq  c_{\min}^2/(10sc_{\max})$ and $\norm{X^\top \varepsilon/n}_{\infty} \leq {\lambda}/4$, the assumptions of Lemma~\ref{lem:L2norm} are satisfied. Combining this lemma with Equation~\eqref{eqn:upperboundL2norm} yields
  \begin{equation*}
    \begin{aligned}
      |r^{\top} x^j/n|&\leq \frac{25{\lambda}^2 sc_{\max}}{c_{\min}^2}
      \leq \frac{{\lambda} \gamma}{4(2-\gamma)}
    \end{aligned}
  \end{equation*}
  for each $j\in [p]$. Thus, $\norm{X^\top r/n}_{\infty}\leq {\lambda} \gamma/(4(2-\gamma))$ as desired.

\label{lem:PDW}
  The pair $({\hat{\alpha}}, {\hat{\nu}})$ defined above satisfies the following three properties:
    \begin{enumerate}
      \item[(i)] It holds that $ {\hat{\nu}_{S}}\in \partial \norm{{\hat{\alpha}_{S}}}_1;$
      \item[(ii)] If $\norm{{\hat{\nu}_{{S}^c}}}_{\infty}<1$, then any solution ${\hat{\beta}}$ to the problem~\eqref{eqn:SLR} satisfies \textnormal{supp}$({\hat{\beta}})\subset S$;
      \item[(iii)] Under Assumption~\ref{Ass:BEC} and $\norm{{\hat{\nu}_{{S}^c}}}_{\infty}<1$, the solution ${\hat{\beta}}$ is unique, and ${\hat{\beta}} = {\hat{\alpha}}=({\hat{\alpha}_{S}}^\top,{\hat{\alpha}_{{S}^c}}^\top)^\top\in {\mathbb{R}}^p$.
    \end{enumerate}

\enspace

We conduct the proof in two steps. The first step is to show that $\textnormal{supp}({\hat{\beta}})\subset S$ and that~${\hat{\beta}}$ is the unique solution of the problem~\eqref{eqn:SLR}. The second step is to show the $\ell_{\infty}$-bound and the result on support recovery.


\textbf{Step 1:}\enspace We first show that $\textnormal{supp}({\hat{\beta}})\subset S$ and that ${\hat{\beta}}$ is the unique solution. This result holds true if the primal-dual pair $({\hat{\alpha}},{\hat{\nu}})\in {\mathbb{R}}^p\times {\mathbb{R}}^p$ constructed as in Lemma~\ref{lem:PDW} satisfies
  $ \norm{{\hat{\nu}_{{S}^c}}}_{\infty}<1$. To show the latter inequality, we use the definition of $\varepsilon$ and Equation~\eqref{eqn:mvt} to rewrite $3.$ in the construction above as
  \[ \sum_{i=1}^n X_{ij} w(x_{i,S},{\beta^*_{S}}) x_{i,S}^\top ({\hat{\alpha}_{S}}-{\beta^*_{S}})/n-\sum_{i=1}^n X_{ij}(\varepsilon_i-r_i)/n+{\lambda} {\hat{\nu}_j}=0 \qquad\quad (j\in[p])\,.\]
 Because $w(x_{i,S},{\beta^*_{S}})=w(x_{i},{\beta^*})$ for each $i\in [n]$, we can  put the above display in the matrix form
  \begin{equation*}
   (X^\top {W} X/n)
   \left(\begin{matrix}
     {\beta^*_{S}}-{\hat{\alpha}_{S}}\\
     0
     \end{matrix}\right)+
     X^\top (\varepsilon-r)/n -{\lambda} \left(
     \begin{matrix}
       {\hat{\nu}_{S}}\\
       {\hat{\nu}_{{S}^c}}
     \end{matrix}\right)=0\,,
   \end{equation*}
   and then in the block matrix form
   \begin{equation*}\label{eqn:BM}
     n^{-1}\left(
     \begin{matrix}
       X_{S}^\top {W} X_{S} & X_{S}^\top {W} X_{{S}^c}\\
       X_{{S}^c}^\top {W} X_{S} &X_{{S}^c}^\top {W} X_{{S}^c}
     \end{matrix}\right)
     \left(\begin{matrix}
     {\beta^*_{S}}-{\hat{\alpha}_{S}}\\
     0
     \end{matrix}\right)+n^{-1}
     \left(\begin{matrix}
       X_{S}^\top(\varepsilon-r)\\
       X_{{S}^c}^\top(\varepsilon-r)
     \end{matrix}\right)





     -{\lambda}\left(
     \begin{matrix}
      {\hat{\nu}_{S}}\\
       {\hat{\nu}_{{S}^c}}
     \end{matrix}\right)=0\,.
   \end{equation*}
   We now solve this equation for ${\lambda}{\hat{\nu}_{{S}^c}}$ and find
   \begin{equation*}\label{eqn:dual}
    {\lambda} {\hat{\nu}_{{S}^c}}=X_{{S}^c}^\top {W} X_{S}({\beta^*_{S}}-{\hat{\alpha}_{S}})/n+X_{{S}^c}^\top(\varepsilon-r)/n\,.
    \end{equation*}
    Since the matrix $X_{S}^\top W X_{S}$ is invertible by Assumption~\ref{Ass:MIC}, we can solve the block matrix equation also for $({\beta^*_{S}}-{\hat{\alpha}_{S}})/n$ and find
   \begin{equation}\label{eqn:para}
     ({\beta^*_{S}}-{\hat{\alpha}_{S}})/n=-(X_{S}^\top {W} X_{S})^{-1}X_{S}^\top(\varepsilon-r)/n+{\lambda}(X_{S}^\top{W} X_{S})^{-1}{\hat{\nu}_{S}}\,.
   \end{equation}
    Combining the two displays yields
   \begin{equation}\label{eqn:tdc}
   \begin{aligned}
   {\lambda} {\hat{\nu}_{{S}^c}}=&-X_{{S}^c}^\top{W} X_{S}(X_{S}^\top {W} X_{S})^{-1}X_{S}^\top(\varepsilon-r)/n+
   X_{{S}^c}^\top(\varepsilon-r)/n\\
   & +{\lambda} X_{{S}^c}^\top {W} X_{S}(X_{S}^\top {W} X_{S})^{-1}{\hat{\nu}_{S}}\,.
   \end{aligned}
   \end{equation}
Taking $\ell_{\infty}$-norms on both sides of Equation~\eqref{eqn:tdc} and using the triangle inequality, we find
\begin{equation*}
  \begin{aligned}
    \norm{{\lambda} {\hat{\nu}_{{S}^c}}}_{\infty} \leq \ & \norm{X_{{S}^c}^\top{W} X_{S}(X_{S}^\top {W} X_{S})^{-1}X_{S}^\top(\varepsilon-r)/n}_{\infty} + \norm{X_{{S}^c}^\top(\varepsilon-r)/n}_{\infty}
    \\  &+{\lambda} \norm{X_{{S}^c}^\top{W} X_{S}(X_{S}^\top {W} X_{S})^{-1}{\hat{\nu}_{S}}}_{\infty}\,.
  \end{aligned}
\end{equation*}
Invoking properties of the induced matrix norms and the $\ell_\infty$-norm and the condition $\norm{{\hat{\nu}_{S}}}_{\infty}\leq 1$ deduced in Lemma~\ref{lem:PDW}, and rearranging the terms then provide us with
   \begin{equation*}
   \begin{aligned}
   \norm{{\lambda} {\hat{\nu}_{{S}^c}}}_{\infty}
   &\leq \opnorm{X_{{S}^c}^\top {W} X_{S}(X_{S}^\top {W} X_{S})^{-1}}_{\infty}\left(\norm{X^\top (\varepsilon-r)/n}_{\infty}+\lambda\right)
   +\norm{X^\top (\varepsilon-r)/n}_{\infty}\,.
   \end{aligned}
   \end{equation*}
   Next, we divide by ${\lambda}$ on both sides, apply Assumption~\ref{Ass:MIC}, use the triangle inequality, and rearrange the terms again to find
   \begin{equation*}
     \begin{aligned}
       \norm{{\hat{\nu}_{{S}^c}}}_{\infty}&\leq(1-\gamma)+\frac{2-\gamma}{{\lambda}}(\norm{X^\top \varepsilon/n
       }_{\infty}+\norm{X^\top r/n}_{\infty})\,.

     \end{aligned}
   \end{equation*}
   By the definition of $\mathcal{T}_{{\lambda}}$, it holds that $\norm{X^\top\varepsilon/n}_{\infty}\leq {\lambda} \gamma/(4(2-\gamma))$, which is equivalent to
   \begin{equation*}
   \frac{2-\gamma}{{\lambda}}\norm{X^\top \varepsilon/n}_{\infty}\leq \frac{\gamma}{4}\,.
   \end{equation*}
   Since $\gamma\in(0,1]$, the condition $\norm{X^\top \varepsilon/n}_{\infty} \leq {\lambda}/4$ in Lemma~\ref{lem:Linfnorm} is satisfied on the event $\mathcal{T}_{{\lambda}}$. Combining this with the assumption ${\lambda} \leq \gamma c_{\min}^2/(100(2-\gamma)sc_{\max})$ implies that $\norm{X^\top r/n}_{\infty}\leq {\lambda}\gamma/(4(2-\gamma))$, see Lemma~\ref{lem:Linfnorm}. Thus,
   \begin{equation*}
     \norm{{\hat{\nu}_{{S}^c}}}_{\infty}\leq(1-\gamma)+\frac{\gamma}{4}+\frac{2-\gamma}{{\lambda}}\norm{X^\top r/n}_{\infty}\leq(1-\gamma)+\frac{\gamma}{4}+\frac{\gamma}{4}<1\,.
   \end{equation*}
  We finally invoke Lemma~\ref{lem:PDW} to conclude that $\textnormal{supp}({\hat{\beta}})\subset S$ and that ${\hat{\beta}} = {\hat{\alpha}}= ({\hat{\alpha}_{S}}^\top,0^\top)^\top \in {\mathbb{R}}^p$ is the unique solution of the problem~\eqref{eqn:SLR}, as desired.


   \textbf{Step 2:}\enspace
   To show the $\ell_{\infty}$-bound, we use Equation~\eqref{eqn:para} and ${\hat{\beta}_{S}}={\hat{\alpha}_{S}}$ from  Step~1 and find

   \begin{equation*}
    \begin{aligned}
    {\beta^*_{S}}-{\hat{\beta}_{S}}&=-(X_{S}^\top {W} X_{S})^{-1}X_{S}^\top(\varepsilon-r)+{\lambda} n(X_{S}^\top {W} X_{S})^{-1}{\hat{\nu}_{S}} \\
    &=-\left(X_{S}^\top {W} X_{S}/n\right)^{-1}\left(X_{S}^\top(\varepsilon-r)/n\right)+{\lambda} \left(X_{S}^\top {W} X_{S}/n\right)^{-1}{\hat{\nu}_{S}}\,.
    \end{aligned}
    \end{equation*}
We then find similarly as before
   \begin{equation*}
     \begin{aligned}
       \norm{{\beta^*_{S}}-{\hat{\beta}_{S}}}_{\infty}
       &\leq \opnorm{(X_{S}^\top {W} X_{S}/n)^{-1}}_{\infty}({\lambda}+\norm{X^\top
       (\varepsilon-r)/n}_{\infty})\,.
     \end{aligned}
   \end{equation*}
   By the definition of $a$, we have
   \begin{equation*}
   \begin{aligned}
   \opnorm{(X_{S}^\top {W} X_{S}/n)^{-1}}_{\infty}\leq a \,\opnorm{(X_{S}^\top {W} X_{S}/n)^{-1}}_{2}

   \leq a/c_{\min}\,.
   \end{aligned}
   \end{equation*}
   Combining this with the bounds on $\norm{X^\top \varepsilon/n}_{\infty}$ and $\norm{X^\top r/n}_{\infty}$ deduced   in Step~1 yields
    \[
   \norm{{\beta^*_{S}}-{\hat{\beta}_{S}}}_{\infty}\leq \frac{a }{c_{\min}}\Big({\lambda} + \frac{{\lambda}\gamma}{4(2-\gamma)}+\frac{{\lambda}\gamma}{4(2-\gamma)}\Big)\leq 1.5a{\lambda}/c_{\min}\,.
   \]
   Since $\textnormal{supp}({\hat{\beta}})\subset S$ by Step~1, the above display implies that
   \[
   \norm{{\beta^*}-{\hat{\beta}}}_{\infty}\leq 1.5a{\lambda}/c_{\min}\,.
   \]
   Consequently, $\textnormal{supp}({\hat{\beta}})= S$ as long as $\min_{j \in S}|{\beta^*_j}|>1.5a{\lambda}/c_{\min}$. This concludes the proof.
   \hfill\ensuremath{\square

